```

#### C. External Python Tool (`recovery.py`)
```python
import struct, sys

BSIZE = 1024
IPB = BSIZE // 64

def read_sb(f):
    f.seek(BSIZE)
    return struct.unpack("<IIIIIIII", f.read(32))

def get_inode(f, inodestart, inum):
    f.seek((inodestart * BSIZE) + (inum * 64))
    return struct.unpack("<hhhhI13I", f.read(64))

def corrupt_inode(img, inum):
    with open(img, "rb+") as f:
        sb = read_sb(f)
        f.seek((sb[6] * BSIZE) + (inum * 64))
        f.write(b'\x00' * 64)
    print(f"Corrupted inode {inum}")

if __name__ == "__main__":
    if sys.argv[1] == "corrupt":
        corrupt_inode("fs.img", int(sys.argv[2]))
```

