### 1. Missing and Updated Source Code

#### `user/directoryWalker.c` (New)
This program recursively traverses the directory tree starting from root or a specified path, demonstrating Requirement 2.2.
```c
#include "kernel/types.h"
#include "kernel/stat.h"
#include "user/user.h"
#include "kernel/fs.h"

void walk(char *path) {
  char buf[512], *p;
  int fd;
  struct dirent de;
  struct stat st;

  if((fd = open(path, 0)) < 0) return;
  if(fstat(fd, &st) < 0 || st.type != T_DIR) {
    close(fd);
    return;
  }

  if(strlen(path) + 1 + DIRSIZ + 1 > sizeof buf) return;
  strcpy(buf, path);
  p = buf+strlen(buf);
  *p++ = '/';

  while(read(fd, &de, sizeof(de)) == sizeof(de)) {
    if(de.inum == 0 || strcmp(de.name, ".") == 0 || strcmp(de.name, "..") == 0)
      continue;
    memmove(p, de.name, DIRSIZ);
    p[DIRSIZ] = 0;
    if(stat(buf, &st) < 0) continue;
    printf("Path: %-20s | Inode: %d | Type: %d\n", buf, de.inum, st.type);
    if(st.type == T_DIR) walk(buf);
  }
  close(fd);
}

int main(int argc, char *argv[]) {
  walk(argc > 1 ? argv[1] : "/");
  exit(0);
}
```

#### `user/imapWalker.c` (Corrected Logic)
Uses the `get_dinode` return value to dynamically detect the end of the inode table.
