### 2. Complete Source Code and Modifications

#### A. Kernel Changes
**kernel/fs.h**: Add `inode_info` structure.
```c
struct inode_info {
  uint type; short major; short minor;
  short nlink; uint size; uint addrs[13];
};
```

**kernel/sysfile.c**: Implement the system call.
```c
uint64 sys_get_dinode(void) {
  int inum; uint64 addr; struct buf *bp; struct dinode *dip; struct superblock sb;
  if(argint(0, &inum) < 0 || argaddr(1, &addr) < 0) return -1;
  bp = bread(1, 1); memmove(&sb, bp->data, sizeof(sb)); brelse(bp);
  if(inum < 0 || inum >= sb.ninodes) return -1;
  bp = bread(1, IBLOCK(inum, sb));
  dip = (struct dinode*)bp->data + (inum % IPB);
  struct inode_info info = {dip->type, dip->major, dip->minor, dip->nlink, dip->size};
  memmove(info.addrs, dip->addrs, sizeof(info.addrs));
  brelse(bp);
  return copyout(myproc()->pagetable, addr, (char *)&info, sizeof(info));
}
```

