#### C. Functional External Recovery Tool (Python)
**recovery_suite.py**
```python
import struct, sys, os
BSIZE = 1024

class XV6Recovery:
    def __init__(self, img):
        self.f = open(img, "rb+")
        self.f.seek(BSIZE)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.inodestart = sb[6]

    def get_inode(self, inum):
        self.f.seek((self.inodestart * BSIZE) + (inum * 64))
        d = struct.unpack("<hhhhI13I", self.f.read(64))
        return {"inum": inum, "type": d[0], "size": d[4], "addrs": d[5:]}

    def get_entries(self, inum):
        ino = self.get_inode(inum)
        if ino['type'] != 1: return []
        entries = []
        for addr in ino['addrs'][:12]:
            if addr == 0: continue
            self.f.seek(addr * BSIZE)
            blk = self.f.read(BSIZE)
            for i in range(0, BSIZE, 16):
                u = struct.unpack("<H14s", blk[i:i+16])
                if u[0] != 0: entries.append((u[0], u[1].strip(b'\x00').decode()))
        return entries

    def repair(self):
        print("--- Starting FS Repair Analysis ---")
        allocated = {i for i in range(1, 200) if self.get_inode(i)['type'] != 0}
        reachable = set()
        def traverse(inum):
            if inum in reachable: return
            reachable.add(inum)
            for cinum, name in self.get_entries(inum):
                if name not in (".", ".."): traverse(cinum)
        traverse(1)
        orphans = allocated - reachable
        for o in orphans: print(f"[!] Orphan Found: Inode {o}")
        if not orphans: print("FS Consistent.")

if __name__ == "__main__":
    tool = XV6Recovery("fs.img")
    tool.repair()
```

