#### C. `recovery_suite.py` (Extended Repair Logic)
```python
import struct, sys

BSIZE = 1024

class Recovery:
    def __init__(self, img):
        self.img = img
        self.f = open(img, "rb+")
        self.f.seek(BSIZE)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.inodestart = sb[6]
        self.ninodes = sb[3]

    def get_inode(self, inum):
        self.f.seek((self.inodestart * BSIZE) + (inum * 64))
        d = struct.unpack("<hhhhI13I", self.f.read(64))
        return {"inum": inum, "type": d[0], "addrs": d[5:]}

    def repair(self):
        allocated = [i for i in range(1, self.ninodes) if self.get_inode(i)['type'] != 0]
        reachable = {1}
        queue = [1]
        while queue:
            curr = queue.pop(0)
            ino = self.get_inode(curr)
