To facilitate out-of-band recovery, we implemented the `get_dinode` system call to allow user-level tools to bypass high-level file system abstractions.

**Modified Files:**
- `kernel/fs.h`: Defined `struct inode_info` to pass raw metadata.
- `kernel/sysfile.c`: Implemented `sys_get_dinode` to read raw disk blocks using `bread`.
- `kernel/syscall.h` / `kernel/syscall.c`: Registered `SYS_get_dinode` (ID 22).
- `user/user.h`: Added system call prototype.
- `user/usys.pl`: Added entry point for the linker.

#### `kernel/fs.h` addition:
```c
struct inode_info {
  uint type;    // Inode type (1=Dir, 2=File, 3=Device)
  short nlink;  // Number of links to inode
  uint size;    // Size of file (bytes)
  uint addrs[13]; // Data block addresses
};
```

#### `kernel/sysfile.c` implementation:
```c
uint64 sys_get_dinode(void) {
  int inum; uint64 addr; struct buf *bp; struct dinode *dip; struct superblock sb;
  if(argint(0, &inum) < 0 || argaddr(1, &addr) < 0) return -1;
  bp = bread(1, 1);
  memmove(&sb, bp->data, sizeof(sb));
  brelse(bp);
  if(inum < 0 || inum >= sb.ninodes) return -1;
  bp = bread(1, IBLOCK(inum, sb));
  dip = (struct dinode*)bp->data + (inum % IPB);
  struct inode_info info = {dip->type, dip->nlink, dip->size};
  memmove(info.addrs, dip->addrs, sizeof(info.addrs));
  brelse(bp);
  return copyout(myproc()->pagetable, addr, (char *)&info, sizeof(info));
}
```

