            if (!isCorrectTime()) {
                console.log("Outside allowed time (22:30-03:30). Waiting...");
                setTimeout(() => location.reload(), 60000);
                return;
            }

            // Step 3: Text Check
            if (document.body.innerText.includes(FORBIDDEN_TEXT)) {
                console.log("Text found. Reloading in 5 seconds...");
                setTimeout(() => location.reload(), 5000);
            } 
            // Step 4: Text NOT found -> Trigger Tab 2
            else {
                console.log("Text not found! Signaling Tab 2...");
                bc.postMessage('TRIGGER_CLICK');
            }
        }

        runLogic();
    } 

    // ==========================================
    // LOGIC FOR TAB 2 (The Action Tab)
    // ==========================================
    else {
        console.log("Tab 2: Ready and listening for signal...");

        bc.onmessage = (event) => {
            if (event.data === 'TRIGGER_CLICK') {
                const btn = document.querySelector(SUBMIT_SELECTOR);
                if (btn) {
                    console.log("Signal received! Clicking submit...");

                    // Step 5: Transition and Click
                    window.focus();
                    btn.click();

                    // Alert forces the browser to highlight/bring the tab to front
                    alert("Reservation Triggered!");
                    bc.close();
                } else {
                    console.error("Trigger received but submit button was not found on this page.");
                }
            }
        };
    }
})();
