This service replaces your .NET Repository. It handles the connection to MongoDB and encapsulates the query logic.

```typescript
import { Injectable } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { Lookup } from './schemas/lookup.schema';

@Injectable()
export class LookupService {
  constructor(@InjectModel(Lookup.name) private lookupModel: Model<Lookup>) {}

  async findByKey(key: string): Promise<Lookup | null> {
    // Normalize input to handle case-sensitivity differences from SQL
    return this.lookupModel.findOne({ lookupKey: key.toLowerCase() }).exec();
  }

  async upsertFromXml(key: string, data: any): Promise<void> {
    await this.lookupModel.updateOne(
      { lookupKey: key.toLowerCase() },
      { data, updatedAt: new Date() },
      { upsert: true }
    );
  }
}
```

