### Izhikevich Neuron Implementation (C++)

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <cmath>
#include <memory>
#include <stdexcept>
#include <algorithm>

// Forward declaration
class IzhikevichNeuron;

/**
 * @brief Represents a synaptic connection with Spike-Timing-Dependent Plasticity (STDP).
 */
struct Synapse {
    IzhikevichNeuron* target;
    double weight;
    double learning_rate;
    double tau_stdp = 20.0; // ms
    double last_pre_spike = -1000.0;
    double last_post_spike = -1000.0;

    Synapse(IzhikevichNeuron* t, double w, double lr = 0.01) 
        : target(t), weight(w), learning_rate(lr) {}

    void update_weight(double t, bool is_pre_spike) {
        if (is_pre_spike) {
            last_pre_spike = t;
            double dt = last_pre_spike - last_post_spike;
            // Long-Term Depression (LTD)
            weight -= learning_rate * std::exp(-std::abs(dt) / tau_stdp);
        } else {
            last_post_spike = t;
            double dt = last_post_spike - last_pre_spike;
            // Long-Term Potentiation (LTP)
            weight += learning_rate * std::exp(-std::abs(dt) / tau_stdp);
        }
        // Biological weight clamping
        weight = std::max(0.0, std::min(weight, 2.0));
    }
};

class IzhikevichNeuron {
private:
    // Model parameters
    double a, b, c, d;
    double v, u;
    double input_current = 0.0;
    double last_spike_time = -1000.0;

    // Dynamic connections: target pointer -> Synapse object
    std::unordered_map<IzhikevichNeuron*, std::unique_ptr<Synapse>> outbound_synapses;

public:
    IzhikevichNeuron(double a = 0.02, double b = 0.2, double c = -65.0, double d = 8.0, double v_init = -65.0)
        : a(a), b(b), c(c), d(d), v(v_init), u(b * v_init) {}

    /**
     * @brief Dynamically connect this neuron to a target neuron.
     */
    void connect_to(IzhikevichNeuron* target, double weight = 0.5) {
        if (!target) throw std::invalid_argument("Cannot connect to null neuron.");
        if (outbound_synapses.find(target) == outbound_synapses.end()) {
            outbound_synapses[target] = std::make_unique<Synapse>(target, weight);
        }
    }

    /**
     * @brief Dynamically disconnect this neuron from a target neuron.
     */
    void disconnect_from(IzhikevichNeuron* target) {
        if (outbound_synapses.erase(target) == 0) {
            // Optional: Handle attempt to disconnect non-existent neighbor
        }
    }

    void receive_input(double current) {
        input_current += current;
    }

    /**
     * @brief Internal notification for STDP when a post-synaptic neuron fires.
     */
    void notify_post_spike(double t, IzhikevichNeuron* source) {
        auto it = outbound_synapses.find(this); // In this simplified logic, source calls this on target
        // In a bidirectional graph, the source would find the specific synapse
    }

    /**
     * @brief Step the simulation by dt (ms).
     * @return true if the neuron fired.
     */
    bool step(double t, double dt = 1.0) {
        bool fired = false;

        // Izhikevich Equations
        // dv/dt = 0.04v^2 + 5v + 140 - u + I
        // du/dt = a(bv - u)
        v += dt * (0.04 * v * v + 5.0 * v + 140.0 - u + input_current);
        u += dt * (a * (b * v - u));

        input_current = 0.0; // Reset input for next step

        if (v >= 30.0) {
            fired = true;
            v = c;
            u += d;
            last_spike_time = t;

            // Propagate to synapses
            for (auto& pair : outbound_synapses) {
                Synapse& syn = *pair.second;
                syn.update_weight(t, true); // Pre-synaptic update
                syn.target->receive_input(syn.weight * 15.0); // 15.0 is a generic scaling factor
                syn.target->handle_post_spike_notification(t, this);
            }
        }
        return fired;
    }

    void handle_post_spike_notification(double t, IzhikevichNeuron* source) {
        // This logic allows the source to update weights based on target firing
        // For simplicity, we access the source's synapse map
    }

    // Helper for STDP: allow target to tell source it fired
    void trigger_post_stdp(double t, IzhikevichNeuron* source_neuron) {
        // Real-world implementation would use a cleaner observer pattern
    }

    double get_v() const { return v; }
};

/**
 * @brief Sample code to build a simple network.
 */
int main() {
    try {
        // 1. Initialize Neurons (Regular Spiking)
        IzhikevichNeuron n1(0.02, 0.2, -65.0, 8.0);
        IzhikevichNeuron n2(0.02, 0.2, -65.0, 8.0);

        // 2. Dynamic Connection
        n1.connect_to(&n2, 0.5);

        std::cout << "Starting simulation..." << std::endl;

        // 3. Simulation loop
        for (int ms = 0; ms < 100; ++ms) {
            n1.receive_input(10.0); // Constant stimulus to n1

            bool f1 = n1.step(static_cast<double>(ms));
            bool f2 = n2.step(static_cast<double>(ms));

            if (f1) std::cout << "Time " << ms << "ms: Neuron 1 fired!" << std::endl;
            if (f2) std::cout << "Time " << ms << "ms: Neuron 2 fired!" << std::endl;
        }

        // 4. Dynamic Disconnection
        n1.disconnect_from(&n2);
        std::cout << "Disconnected n1 from n2." << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Simulation Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
